# coding: latin-1
"""Parse and export textual sensitivity reports generated by PSS/E.

Returns a dict of four DataFrames (one per PSS/E report subsection):
  - bus_name        : sensitivities from generator buses
  - load_bus        : sensitivities from load buses
  - tap_transformers: sensitivities from tap-changing transformers
  - switched_shunts : sensitivities from switched shunts

All DataFrames have VARIABLE and ELEMENTO as the first columns.
"""

import os
import re
import pandas as pd

# ---------------------------------------------------------------------------
# Header regexes
# ---------------------------------------------------------------------------
_BRANCH_HDR = re.compile(
    r"SENSITIVITY FACTORS OF BRANCH FLOW\s*\(([^)]+)\)\s+ON(.*)MORE THAN",
    re.IGNORECASE,
)

_VOLT_HDR = re.compile(
    r"SENSITIVITY FACTORS OF BUS VOLTAGE\s*\(([^)]+)\)\s+AT THE BUS(.*?)MORE THAN",
    re.IGNORECASE,
)

_SEC_RE = re.compile(
    r"<[- ]*(BUS NAME|LOAD BUS|GENERATOR BUS|TAP CHANGING TRANSFORMERS|SWITCHED SHUNTS)[ -]*>",
    re.IGNORECASE,
)

# ---------------------------------------------------------------------------
# Column definitions (empty frames)
# ---------------------------------------------------------------------------
_EMPTY_TABLES = {
    "bus_name": ["VARIABLE", "ELEMENTO", "BUS", "MW_SENS", "MVAR_SENS"],
    "load_bus": ["VARIABLE", "ELEMENTO", "BUS", "LOAD_MW", "LOAD_MVAR", "MW_SENS", "MVAR_SENS"],
    "tap_transformers": ["VARIABLE", "ELEMENTO", "BRANCH", "TAP", "RMAX", "RMIN", "SENS"],
    "switched_shunts": ["VARIABLE", "ELEMENTO", "BUS", "BINT", "BMAX", "BMIN", "SENS"],
}

_SHEET_NAMES = {
    "bus_name": "BUS NAME",
    "load_bus": "LOAD BUS",
    "tap_transformers": "TAP TRANSFORMERS",
    "switched_shunts": "SWITCHED SHUNTS",
}

def _empty_result():
    return {k: pd.DataFrame(columns=v) for k, v in _EMPTY_TABLES.items()}


# ---------------------------------------------------------------------------
# Header parsers
# ---------------------------------------------------------------------------
def _parse_branch_header(m):
    ft = m.group(1).strip()
    var_type = "V" if ft.lower() == "pu" else ft.upper()
    return {
        "elem_kind": "BRANCH",
        "variable": var_type,
        "raw_element": m.group(2).strip()
    }

def _parse_volt_header(m):
    ft = m.group(1).strip()
    var_type = "V" if ft.lower() == "pu" else ft.upper()
    return {
        "elem_kind": "VOLTAGE",
        "variable": var_type,
        "raw_element": m.group(2).strip()
    }


# ---------------------------------------------------------------------------
# Data line parsers (one per subsection type)
# ---------------------------------------------------------------------------
def _parse_bus_name(fields, is_voltage):
    """bus name... kv mw_sens [mvar_sens]"""
    bus = fields[0]
    if is_voltage:
        mvar = float(fields[-1])
        mw = float(fields[-2])
        kv = fields[-3]
        name = " ".join(fields[1:-3])
        combined_bus = "{} {} {}".format(bus, name, kv)
        return {"BUS": combined_bus, "MW_SENS": mw, "MVAR_SENS": mvar}
    else:
        mw = float(fields[-1])
        kv = fields[-2]
        name = " ".join(fields[1:-2])
        combined_bus = "{} {} {}".format(bus, name, kv)
        return {"BUS": combined_bus, "MW_SENS": mw, "MVAR_SENS": None}


def _parse_load_bus(fields, is_voltage):
    """bus name... kv load_mw [load_mvar] mw_sens [mvar_sens]"""
    bus = fields[0]
    if is_voltage and len(fields) >= 7:
        mvar_sens = float(fields[-1])
        mw_sens = float(fields[-2])
        load_mvar = float(fields[-3])
        load_mw = float(fields[-4])
        kv = fields[-5]
        name = " ".join(fields[1:-5])
        combined_bus = "{} {} {}".format(bus, name, kv)
        return {"BUS": combined_bus, 
                "LOAD_MW": load_mw, "LOAD_MVAR": load_mvar,
                "MW_SENS": mw_sens, "MVAR_SENS": mvar_sens}
    elif len(fields) >= 5:
        mw_sens = float(fields[-1])
        load_mw = float(fields[-2])
        kv = fields[-3]
        name = " ".join(fields[1:-3])
        combined_bus = "{} {} {}".format(bus, name, kv)
        return {"BUS": combined_bus, 
                "LOAD_MW": load_mw, "LOAD_MVAR": None,
                "MW_SENS": mw_sens, "MVAR_SENS": None}
    return None


def _parse_tap_line(fields):
    """from_bus from_name... from_kv to_bus to_name... to_kv ckt tap rmax rmin sens"""
    sens = float(fields[-1])
    rmin = float(fields[-2])
    rmax = float(fields[-3])
    tap = float(fields[-4])
    ckt = fields[-5]
    rest = fields[:-5]
    
    from_bus = rest[0]
    i = 1
    from_name_parts = []
    from_kv = ""
    while i < len(rest):
        try:
            _ = float(rest[i]) # Verify it's a float
            from_kv = rest[i]
            i += 1
            break
        except ValueError:
            from_name_parts.append(rest[i])
            i += 1
            
    to_bus = rest[i] if i < len(rest) and rest[i].isdigit() else ""
    i += 1
    to_name_parts = []
    to_kv = ""
    while i < len(rest):
        try:
            _ = float(rest[i]) # Verify it's a float
            to_kv = rest[i]
            i += 1
            break
        except ValueError:
            to_name_parts.append(rest[i])
            i += 1
            
    from_name = " ".join(from_name_parts)
    to_name = " ".join(to_name_parts)
    
    combined_from = "{} {} {}".format(from_bus, from_name, from_kv).strip()
    combined_to = "{} {} {}".format(to_bus, to_name, to_kv).strip()
    combined_branch = "{} TO {} CKT {}".format(combined_from, combined_to, ckt)
    
    return {
        "BRANCH": combined_branch,
        "TAP": tap, "RMAX": rmax, "RMIN": rmin, "SENS": sens,
    }


def _parse_shunt_line(fields):
    """bus name... kv bint bmax bmin sens"""
    bus = fields[0]
    sens = float(fields[-1])
    bmin = float(fields[-2])
    bmax = float(fields[-3])
    bint = float(fields[-4])
    kv = fields[-5]
    name = " ".join(fields[1:-5])
    
    combined_bus = "{} {} {}".format(bus, name, kv)
    
    return {"BUS": combined_bus,
            "BINT": bint, "BMAX": bmax, "BMIN": bmin, "SENS": sens}


# ---------------------------------------------------------------------------
# Main parser
# ---------------------------------------------------------------------------
def parse_sensitivity_report(report_file):
    """Parse a PSS/E sensitivity report into a dict of 4 DataFrames.

    Returns:
        dict with keys: bus_name, load_bus, tap_transformers, switched_shunts.
        Each value is a DataFrame with VARIABLE and ELEMENTO as the first columns.
    """
    if not os.path.exists(report_file):
        return _empty_result()

    with open(report_file, "r") as fh:
        lines = fh.read().splitlines()

    rows = {k: [] for k in _EMPTY_TABLES}
    header = {}
    section = None

    for line in lines:
        stripped = line.strip()

        bm = _BRANCH_HDR.search(line)
        if bm:
            header = _parse_branch_header(bm)
            section = None
            continue

        vm = _VOLT_HDR.search(line)
        if vm:
            header = _parse_volt_header(vm)
            section = None
            continue

        sm = _SEC_RE.search(line)
        if sm:
            section = sm.group(1).upper()
            continue

        if not header or not section:
            continue

        fields = stripped.split()
        if not fields or not fields[0].isdigit():
            continue

        label = header["raw_element"]
        var_type = header["variable"]
        is_voltage = header["elem_kind"] == "VOLTAGE"

        try:
            if section == "BUS NAME":
                row = _parse_bus_name(fields, is_voltage)
                row["ELEMENTO"] = label
                row["VARIABLE"] = var_type
                rows["bus_name"].append(row)
            elif section == "LOAD BUS":
                row = _parse_load_bus(fields, is_voltage)
                if row is not None:
                    row["ELEMENTO"] = label
                    row["VARIABLE"] = var_type
                    rows["load_bus"].append(row)
            elif section == "TAP CHANGING TRANSFORMERS":
                row = _parse_tap_line(fields)
                row["ELEMENTO"] = label
                row["VARIABLE"] = var_type
                rows["tap_transformers"].append(row)
            elif section == "SWITCHED SHUNTS":
                row = _parse_shunt_line(fields)
                row["ELEMENTO"] = label
                row["VARIABLE"] = var_type
                rows["switched_shunts"].append(row)
        except (ValueError, IndexError):
            continue

    result = {}
    for key, cols in _EMPTY_TABLES.items():
        if rows[key]:
            df = pd.DataFrame(rows[key], columns=cols)
        else:
            df = pd.DataFrame(columns=cols)
        result[key] = df

    return result


# ---------------------------------------------------------------------------
# Excel writer
# ---------------------------------------------------------------------------
def write_sensitivity_excel(tables, output_file):
    """Write a dict of DataFrames to a multi-sheet Excel file.
    
    Args:
        tables: dict returned by parse_sensitivity_report (or a merged version).
        output_file: destination .xlsx path.
    """
    with pd.ExcelWriter(output_file) as writer:
        for key, sheet in _SHEET_NAMES.items():
            tables[key].to_excel(writer, sheet_name=sheet, index=False)


def save_sensitivity_table(report_file, output_file):
    """Parse a PSS/E report and save results as a multi-sheet Excel file.
    
    Args:
        report_file: Path to the source text report.
        output_file: Destination path for the .xlsx table.
        
    Returns:
        The dict of DataFrames written to output_file.
    """
    tables = parse_sensitivity_report(report_file)
    write_sensitivity_excel(tables, output_file)
    return tables
